  return t.includes('nao') && (
    t.includes('produto') ||
    t.includes('material') ||
    t.includes('peca') ||
    t.includes('usou') ||
    t.includes('usado') ||
    t.includes('gastei')
  );
}

function supabasePatch(osCodigo, body) {
  try {
    const url = SUPABASE_URL + '?os_codigo=eq.' + encodeURIComponent(osCodigo);
    return $helpers.httpRequest({
      method: 'PATCH',
      url: url,
      headers: {
        'apikey': SUPABASE_ANON_KEY,
        'Authorization': 'Bearer ' + SUPABASE_ANON_KEY,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation',
      },
      body: body,
    });
  } catch (e) {
    return null;
  }
}

function bomsaldoPatch(osIdBomsaldo, body) {
  try {
    if (!osIdBomsaldo) return null;
    const url = BOMSALDO_API_URL + '/ordens_servicos/' + encodeURIComponent(osIdBomsaldo) + '/';
    return $helpers.httpRequest({
      method: 'PATCH',
      url: url,
      headers: {
        'access-token': BOMSALDO_ACCESS_TOKEN,
        'secret-access-token': BOMSALDO_SECRET_TOKEN,
        'Content-Type': 'application/json',
      },
      body: body,
    });
  } catch (e) {
    return null;
  }
}

function salvarCampoSupabase(campo, valor, extra) {
  var osCodigo = extra && extra.os_codigo;
  var osIdBomsaldo = extra && extra.os_id_bomsaldo;
  if (!osCodigo) return { ok: false, campo: campo, erro: 'Sem os_codigo' };

  var updateBody = {};
  updateBody[campo] = valor;
  if (extra && extra.fase_ia) updateBody.fase_ia = extra.fase_ia;
  if (extra && extra.observacoes_orientacao) updateBody.observacoes_orientacao = extra.observacoes_orientacao;
  updateBody.atualizado_em = new Date().toISOString();

  var supabaseResult = supabasePatch(osCodigo, updateBody);
  var bomsaldoResult = osIdBomsaldo ? bomsaldoPatch(osIdBomsaldo, updateBody) : null;

  return {
    ok: true,
    campo: campo,
    valor: String(valor || '').slice(0, 200),
    supabase: supabaseResult ? 'ok' : 'falha',
    bomsaldo: bomsaldoResult ? 'ok' : (osIdBomsaldo ? 'falha' : 'nao_aplicavel'),
  };
}

