function firstJson(nodeName) {
  try {
    const value = $(nodeName).first().json || {};
    if (Array.isArray(value)) return value[0] || {};
    if (Array.isArray(value.data)) return value.data[0] || {};
    return value;
  } catch (e) {
    return {};
  }
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function hasValue(value) {
  if (value === null || value === undefined) return false;
  if (typeof value === 'boolean') return true;
  if (typeof value === 'number') return true;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === 'object') return Object.keys(value).length > 0;
  const text = String(value).trim();
  return text !== '' && text !== '[]' && text !== '{}' && text.toLowerCase() !== 'null';
}

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (!hasValue(value)) return [];
  if (typeof value === 'object') return Object.keys(value).length ? [value] : [];
  try {
    const parsed = JSON.parse(String(value));
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

function productStepAlreadyHandled(os) {
  if (parseJsonArray(os.produtos_json).length > 0) return true;
  const obs = normalizeText(os.observacoes_orientacao);
  return obs.includes('sem produto') ||
    obs.includes('sem material') ||
    obs.includes('nao usou produto') ||
    obs.includes('nao usou material') ||
    obs.includes('nao houve produto') ||
    obs.includes('nao houve material');
}

function looksLikeCommand(text) {
  return text.includes('qual os') ||
    text.includes('tenho aberta') ||
    text === 'continua' ||
    text === 'continuar' ||
    text.includes('preencher a os') ||
    text.includes('vamos continuar') ||
    text.includes('abrir nova') ||
    text.includes('nova os') ||
    text.includes('cancelar');
}

function looksTechnical(text) {
  if (!text || looksLikeCommand(text)) return false;
  return [
    'problema',
    'defeito',
    'quebrad',
    'cremalheira',
    'motor',
    'portao',
    'porta',
    'camera',
    'alarme',
    'central',
    'sensor',
    'interfone',
    'sem comunicacao',
    'sem imagem',
    'nao abre',
    'nao fecha',
    'nao arma',
    'falha',
    'tava',
    'estava',
  ].some((term) => text.includes(term));
}

function looksSolution(text) {
  if (!text || looksLikeCommand(text)) return false;
  return [
    'troquei',
    'troca',
    'substitui',
    'substituicao',
    'ajustei',
    'regulei',
    'reparei',
    'corrigi',
    'reconfigurei',
    'instalei',
    'limpei',
  ].some((term) => text.includes(term));
}

function extractHoraEntrada(raw) {
  const text = normalizeText(raw);
  const m = text.match(/(?:cheguei|local|cliente|sim)?\s*(?:as|às|a)?\s*(\d{1,2})(?::|h|hs)?(\d{2})?/);
  if (!m || !text.includes('cheg')) return '';
  const hour = Number(m[1]);
  const minute = m[2] ? Number(m[2]) : 0;
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return '';
  return String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
}

const os = firstJson('BuscarTecnico');
const info = firstJson('setarInfo');
const mensagemRaw = String(info.msgLead || '').trim();
const mensagem = normalizeText(mensagemRaw);
const campos = [
  'defeito',
  'causa',
  'solucao',
  'equipamento',
  'marca',
  'modelo',
  'relatorio_tecnico',
  'observacoes_orientacao',
  'hora_entrada',
  'hora_saida',
  'em_garantia',
  'tipo_pagamento',
  'valor_total',
  'produtos_json',
  'servicos_json',
  'qtd_evidencias',
  'link_pasta_drive',
  'status_os',
  'fase_ia',
  'os_codigo',
  'os_id_bomsaldo',
  'cliente_nome',
  'tecnico_id',
  'tecnico_nome',
  'tecnico_whatsapp',
  'atualizado_em',
];

const campos_preenchidos = campos.filter((campo) => hasValue(os[campo]));
const campos_pendentes = campos.filter((campo) => !hasValue(os[campo]));
const produtosTratados = productStepAlreadyHandled(os);
const obsNormalizada = normalizeText(os.observacoes_orientacao);
const emGarantiaPreenchido = os.em_garantia === true ||
  normalizeText(os.em_garantia) === 'true' ||
  obsNormalizada.includes('garantia') ||
  obsNormalizada.includes('cobrado') ||
  obsNormalizada.includes('cobranca') ||
  hasValue(os.tipo_pagamento);
const cobrado = obsNormalizada.includes('cobrado') ||
  obsNormalizada.includes('cobranca') ||
  hasValue(os.tipo_pagamento);
const reclamacaoRepeticao = mensagem.includes('de novo') || mensagem.includes('ja falei') || mensagem.includes('voce ja perguntou') || mensagem.includes('você já perguntou');
let campo_sugerido = '';
let valor_sugerido = '';
let acao_sugerida = '';

let proximo_passo = 'sem_os_ativa';
let instrucao_vanda = 'Se nao houver OS ativa, ajude o tecnico a localizar ou abrir uma OS.';

if (hasValue(os.os_codigo)) {
  if (!hasValue(os.defeito) && !hasValue(os.relatorio_tecnico)) {
    proximo_passo = 'pedir_defeito';
    instrucao_vanda = 'Pergunte o problema relatado pelo cliente ou defeito encontrado.';
    if (looksTechnical(mensagem)) {
      campo_sugerido = 'defeito';
      valor_sugerido = mensagemRaw;
      acao_sugerida = 'salvarContexto';
      instrucao_vanda = 'A mensagem atual informa o defeito. Chame salvarContexto com defeito=valor_sugerido, observacoes_orientacao=valor_sugerido e fase_ia=coleta_tecnica. Depois pergunte horario de chegada.';
    }
  } else if (hasValue(os.defeito) && !hasValue(os.hora_entrada)) {
    proximo_passo = 'pedir_chegada';
    instrucao_vanda = 'Pergunte horario de chegada.';
    const hora = extractHoraEntrada(mensagemRaw);
    if (hora) {
      campo_sugerido = 'hora_entrada';
      valor_sugerido = hora;
      acao_sugerida = 'atualizarOS_hora_entrada';
      instrucao_vanda = 'A mensagem atual informa chegada. Chame atualizarOS com os_id=os_id_bomsaldo, os_codigo e hora_entrada=valor_sugerido. Depois pergunte a causa encontrada.';
    }
  } else if (hasValue(os.hora_entrada) && !hasValue(os.causa)) {
    proximo_passo = 'pedir_causa';
    instrucao_vanda = 'Pergunte a causa encontrada. Nao pergunte chegada novamente.';
    if (looksTechnical(mensagem) || (!looksLikeCommand(mensagem) && mensagem.length >= 4 && !reclamacaoRepeticao)) {
      campo_sugerido = 'causa';
      valor_sugerido = mensagemRaw;
      acao_sugerida = 'salvarContexto';
      instrucao_vanda = 'A mensagem atual informa a causa. Chame salvarContexto com causa=valor_sugerido e fase_ia=coleta_tecnica. Depois pergunte qual foi a solucao aplicada.';
    }
  } else if (hasValue(os.causa) && !hasValue(os.solucao)) {
    proximo_passo = 'pedir_solucao';
    instrucao_vanda = 'Pergunte a solucao aplicada.';
    if (looksSolution(mensagem)) {
      campo_sugerido = 'solucao';
      valor_sugerido = mensagemRaw;
      acao_sugerida = 'salvarContexto';
      instrucao_vanda = 'A mensagem atual informa a solucao. Chame salvarContexto com solucao=valor_sugerido e fase_ia=coleta_tecnica. Depois pergunte se foi usado algum material/produto.';
    }
  } else if (hasValue(os.solucao) && !produtosTratados) {
    proximo_passo = 'perguntar_produtos';
    instrucao_vanda = 'Pergunte se foi usado algum material/produto.';
    if (looksSolution(mensagem)) {
      instrucao_vanda = 'A solucao ja esta registrada. Nao chame tool para esta repeticao. Pergunte apenas se foi usado algum material/produto.';
    } else if (mensagem.includes('nao') && (mensagem.includes('produto') || mensagem.includes('material') || mensagem.includes('peca'))) {
      campo_sugerido = 'observacoes_orientacao';
      valor_sugerido = 'Sem material/produto utilizado.';
      acao_sugerida = 'salvarContexto';
      instrucao_vanda = 'A mensagem atual informa que nao houve material/produto. Chame salvarContexto com observacoes_orientacao=valor_sugerido e fase_ia=coleta_tecnica. Depois pergunte se e garantia ou cobrado.';
    }
  } else if (!emGarantiaPreenchido) {
    proximo_passo = 'perguntar_garantia_ou_cobranca';
    instrucao_vanda = 'Pergunte se e garantia ou cobrado.';
  } else if (cobrado && !hasValue(os.tipo_pagamento)) {
    proximo_passo = 'pedir_pagamento';
    instrucao_vanda = 'Pergunte forma de pagamento.';
  } else if (!hasValue(os.hora_saida)) {
    proximo_passo = 'pedir_saida';
    instrucao_vanda = 'Pergunte horario de saida.';
  } else {
    proximo_passo = 'pronto_para_fechar';
    instrucao_vanda = 'Fechar OS com atualizarOS.';
  }
}

if (reclamacaoRepeticao && hasValue(os.os_codigo)) {
  instrucao_vanda = 'Peca desculpas de forma curta, diga que ja registrou os dados existentes e avance para o proximo campo pendente: ' + instrucao_vanda;
}

return [{
  json: {
    os_ativa: os,
    campos_preenchidos,
    campos_pendentes,
    proximo_passo,
    instrucao_vanda,
    campo_sugerido,
    valor_sugerido,
    acao_sugerida,
    produtos_tratados: produtosTratados,
    reclamacao_repeticao: reclamacaoRepeticao,
  },
}];
